app.get("/api/cart", authenticateToken, async (req, res) => {
  try {
    const cart = await db.get("SELECT * FROM carrinho WHERE ID_Cliente = ?", [
      req.user.id,
    ]);
    if (!cart) return res.json([]);

    const items = await db.all(
      `SELECT ic.*, 
              COALESCE(p.Nome, w.Titulo) AS Nome,
              COALESCE(p.Preco, w.Preco) AS Preco,
              COALESCE(p.Stock, w.Vagas) AS Stock,
              COALESCE(p.Imagem, w.Imagem) AS Imagem
       FROM item_carrinho ic 
       LEFT JOIN produto p ON ic.ID_Produto = p.ID_Produto 
       LEFT JOIN workshop w ON ic.ID_Workshop = w.ID_Workshop
       WHERE ic.ID_Carrinho = ?`,
      [cart.ID_Carrinho],
    );

    for (const item of items) {
      if (item.Quantidade > item.Stock) {
        await db.run(
          "UPDATE item_carrinho SET Quantidade = ? WHERE ID_itemCarrinho = ?",
          [item.Stock, item.ID_itemCarrinho]
        );
        item.Quantidade = item.Stock;
      }
    }

    res.json(items);
  } catch (error) {
    console.error("Cart fetch error:", error);
    res.status(500).json({ error: "Server error" });
  }
});

