app.post("/api/cart/add", authenticateToken, async (req, res) => {
  const { productId, workshopId, quantity } = req.body;

  try {
    let itemTitle = "";
    let itemStock = 0;
    let isWorkshop = false;

    if (workshopId) {
      isWorkshop = true;
      const workshop = await db.get("SELECT Titulo as Nome, Vagas as Stock FROM workshop WHERE ID_Workshop = ?", [workshopId]);
      if (!workshop) {
        return res.status(404).json({ error: "Workshop não encontrado" });
      }
      itemTitle = workshop.Nome;
      itemStock = workshop.Stock;
    } else if (productId) {
      const product = await db.get("SELECT Nome, Stock FROM produto WHERE ID_Produto = ?", [productId]);
      if (!product) {
        return res.status(404).json({ error: "Produto não encontrado" });
      }
      itemTitle = product.Nome;
      itemStock = product.Stock;
    } else {
      return res.status(400).json({ error: "ID de produto ou workshop em falta." });
    }

    if (isWorkshop) {
      // Check if user already has a PAID/CONFIRMED reservation
      const existingRes = await db.get(
        "SELECT * FROM reserva_workshop WHERE ID_Workshop = ? AND ID_Cliente = ? AND Status = 'Pago'",
        [workshopId, req.user.id]
      );
      if (existingRes) {
        return res.status(400).json({ error: "Já tens uma reserva ativa para este workshop." });
      }
    }

    // 1. Ensure cart exists
    let cart = await db.get("SELECT * FROM carrinho WHERE ID_Cliente = ?", [
      req.user.id,
    ]);
    let cartId;

    if (!cart) {
      const result = await db.run(
        "INSERT INTO carrinho (ID_Cliente) VALUES (?)",
        [req.user.id],
      );
      cartId = result.lastID;
    } else {
      cartId = cart.ID_Carrinho;
    }

    // 2. Add or update item
    let queryExisting = isWorkshop
      ? "SELECT * FROM item_carrinho WHERE ID_Carrinho = ? AND ID_Workshop = ?"
      : "SELECT * FROM item_carrinho WHERE ID_Carrinho = ? AND ID_Produto = ?";
    let existingParam = isWorkshop ? workshopId : productId;

    const existing = await db.get(queryExisting, [cartId, existingParam]);

    const requestedQty = isWorkshop ? 1 : (quantity || 1);
    const currentQtyInCart = existing ? existing.Quantidade : 0;
    const totalRequested = currentQtyInCart + requestedQty;

    // For workshops, max quantity is always 1
    if (isWorkshop && totalRequested > 1) {
      return res.status(400).json({
        error: "Apenas podes reservar 1 vaga para ti neste workshop."
      });
    }

    if (totalRequested > itemStock) {
      return res.status(400).json({ 
        error: isWorkshop
          ? `Apenas existem ${itemStock} vagas disponíveis para o workshop "${itemTitle}".`
          : `Apenas existem ${itemStock} unidades disponíveis em stock para o produto "${itemTitle}".`
      });
    }

    if (existing) {
      await db.run(
        "UPDATE item_carrinho SET Quantidade = ? WHERE ID_itemCarrinho = ?",
        [totalRequested, existing.ID_itemCarrinho],
      );
    } else {
      if (isWorkshop) {
        await db.run(
          "INSERT INTO item_carrinho (ID_Carrinho, ID_Workshop, Quantidade) VALUES (?, ?, ?)",
          [cartId, workshopId, requestedQty],
        );
      } else {
        await db.run(
          "INSERT INTO item_carrinho (ID_Carrinho, ID_Produto, Quantidade) VALUES (?, ?, ?)",
          [cartId, productId, requestedQty],
        );
      }
    }

    res.json({ message: isWorkshop ? "Workshop adicionado ao carrinho" : "Item added to cart" });
  } catch (error) {
    console.error("Add to cart error:", error);
    res.status(500).json({ error: "Server error" });
  }
});

