      WHERE ic.ID_itemCarrinho = ?
    `, [itemId]);

    if (!item) {
      return res.status(404).json({ error: "Item do carrinho não encontrado" });
    }

    // For workshops, quantity is strictly limited to 1
    if (item.ID_Workshop && quantity > 1) {
      return res.status(400).json({ error: "Apenas podes reservar 1 vaga para ti neste workshop." });
