app.post("/api/workshops/:id/reserve", authenticateToken, async (req, res) => {
  const { id } = req.params;
  try {
    const workshop = await db.get(
      "SELECT * FROM workshop WHERE ID_Workshop = ?",
      [id],
    );
    if (!workshop)
      return res.status(404).json({ error: "Workshop não encontrado." });

    if (workshop.Vagas <= 0) {
      return res
        .status(400)
        .json({ error: "Este workshop já não tem vagas disponíveis." });
    }

    const isPaid = parseFloat(workshop.Preco) > 0;

    if (isPaid) {
      // Check if user already has a PAID/CONFIRMED reservation
      const existing = await db.get(
        "SELECT * FROM reserva_workshop WHERE ID_Workshop = ? AND ID_Cliente = ? AND Status = 'Pago'",
        [id, req.user.id],
      );
      if (existing) {
        return res
          .status(400)
          .json({ error: "Já tens uma reserva para este workshop." });
      }

      // Ensure cart exists
      let cart = await db.get("SELECT * FROM carrinho WHERE ID_Cliente = ?", [
        req.user.id,
      ]);
      let cartId;

      if (!cart) {
        const result = await db.run(
          "INSERT INTO carrinho (ID_Cliente) VALUES (?)",
          [req.user.id],
        );
        cartId = result.lastID;
      } else {
        cartId = cart.ID_Carrinho;
      }

      // Check if already in cart
      const inCart = await db.get(
        "SELECT * FROM item_carrinho WHERE ID_Carrinho = ? AND ID_Workshop = ?",
        [cartId, id]
      );

      if (!inCart) {
        await db.run(
          "INSERT INTO item_carrinho (ID_Carrinho, ID_Workshop, Quantidade) VALUES (?, ?, 1)",
          [cartId, id]
        );
      }

      res.json({ ok: true, addedToCart: true, message: "Workshop adicionado ao carrinho para pagamento!" });
    } else {
      // Free workshop reservation
      const existing = await db.get(
        "SELECT * FROM reserva_workshop WHERE ID_Workshop = ? AND ID_Cliente = ?",
        [id, req.user.id],
      );
      if (existing) {
        return res
          .status(400)
          .json({ error: "Já tens uma reserva para este workshop." });
      }

      await db.run(
        "INSERT INTO reserva_workshop (ID_Workshop, ID_Cliente, Status) VALUES (?, ?, 'Pago')",
        [id, req.user.id],
      );
      await db.run(
        "UPDATE workshop SET Vagas = Vagas - 1 WHERE ID_Workshop = ?",
        [id],
      );

      res.json({ ok: true, message: "Reserva efetuada com sucesso!" });
    }
  } catch (error) {
    console.error("Workshop reserve error:", error);
    res.status(500).json({ error: "Erro na base de dados." });
  }
});

