app.post("/api/checkout/init", authenticateToken, async (req, res) => {
  const { address, phone, nome, apelido, shippingCost, shippingType, orderId } =
    req.body;

  try {
    let items = [];
    let subtotal = 0;

    if (orderId) {
      // If we have an orderId, we are updating an existing order
      const order = await db.get(
        "SELECT * FROM encomenda WHERE ID_Encomenda = ? AND ID_Cliente = ?",
        [orderId, req.user.id],
      );
      if (!order)
        return res.status(404).json({ error: "Encomenda não encontrada" });

      // Get items from that order (products)
      const prodItems = await db.all(
        "SELECT ie.*, 1 as isProduct FROM item_encomenda ie WHERE ie.ID_Encomenda = ?",
        [orderId],
      );
      // Get items from that order (workshops)
      const wsItems = await db.all(
        `SELECT rw.ID_Workshop, rw.ID_Cliente, rw.ID_Encomenda, 1 as Quantidade, w.Preco as Preco_Unitario, 0 as isProduct
         FROM reserva_workshop rw
         JOIN workshop w ON rw.ID_Workshop = w.ID_Workshop
         WHERE rw.ID_Encomenda = ?`,
        [orderId]
      );
      items = [
        ...prodItems.map(p => ({ ...p, ID_Produto: p.ID_Produto, Preco: p.Preco_Unitario })),
        ...wsItems.map(w => ({ ...w, ID_Workshop: w.ID_Workshop, Preco: w.Preco_Unitario }))
      ];
      subtotal = items.reduce(
        (sum, item) => sum + item.Preco * item.Quantidade,
        0,
      );
    } else {
      // If no orderId, we must have a cart
      const cart = await db.get("SELECT * FROM carrinho WHERE ID_Cliente = ?", [
        req.user.id,
      ]);
      if (!cart) return res.status(400).json({ error: "Carrinho vazio" });

      items = await db.all(
        `SELECT ic.*, 
                COALESCE(p.Preco, w.Preco) AS Preco,
                COALESCE(p.Nome, w.Titulo) AS Nome,
                COALESCE(p.Stock, w.Vagas) AS Stock
         FROM item_carrinho ic 
         LEFT JOIN produto p ON ic.ID_Produto = p.ID_Produto 
         LEFT JOIN workshop w ON ic.ID_Workshop = w.ID_Workshop
         WHERE ic.ID_Carrinho = ?`,
        [cart.ID_Carrinho],
      );

      if (items.length === 0)
        return res.status(400).json({ error: "Carrinho vazio" });

      // Check stock availability
      for (const item of items) {
        if (item.Quantidade > item.Stock) {
          return res.status(400).json({
            error: item.ID_Workshop
              ? `Apenas existem ${item.Stock} vagas disponíveis para o workshop "${item.Nome}".`
              : `Apenas existem ${item.Stock} unidades disponíveis em stock para o produto "${item.Nome}".`
          });
        }
      }

      subtotal = items.reduce(
        (sum, item) => sum + item.Preco * item.Quantidade,
        0,
      );
    }

    const total = subtotal + Number(shippingCost || 0);
    let currentOrderId = orderId;

    if (currentOrderId) {
      // Update existing draft
      await db.run(
        "UPDATE encomenda SET Total = ?, Morada = ?, Telefone = ?, Nome = ?, Apelido = ?, Custo_Envio = ?, Tipo_Envio = ?, Data_Encomenda = CURRENT_TIMESTAMP WHERE ID_Encomenda = ? AND ID_Cliente = ?",
        [
          total,
          address,
          phone,
          nome,
          apelido,
          shippingCost,
          shippingType,
          currentOrderId,
          req.user.id,
        ],
      );

      if (!orderId) {
        // If finalOrderId was initialized just now from cart, refresh items
        await db.run("DELETE FROM item_encomenda WHERE ID_Encomenda = ?", [
          currentOrderId,
        ]);
        const existingWS = await db.all("SELECT ID_Workshop, COUNT(*) as count FROM reserva_workshop WHERE ID_Encomenda = ? GROUP BY ID_Workshop", [currentOrderId]);
        for (const ews of existingWS) {
          await db.run("UPDATE workshop SET Vagas = Vagas + ? WHERE ID_Workshop = ?", [ews.count, ews.ID_Workshop]);
        }
        await db.run("DELETE FROM reserva_workshop WHERE ID_Encomenda = ?", [currentOrderId]);

        for (const item of items) {
          if (item.ID_Produto) {
            await db.run(
              "INSERT INTO item_encomenda (ID_Encomenda, ID_Produto, Quantidade, Preco_Unitario) VALUES (?, ?, ?, ?)",
              [currentOrderId, item.ID_Produto, item.Quantidade, item.Preco],
            );
            await db.run(
              "UPDATE produto SET Stock = Stock - ? WHERE ID_Produto = ?",
              [item.Quantidade, item.ID_Produto],
            );
          } else if (item.ID_Workshop) {
            await db.run(
              "INSERT INTO reserva_workshop (ID_Workshop, ID_Cliente, ID_Encomenda, Status) VALUES (?, ?, ?, 'Pendente')",
              [item.ID_Workshop, req.user.id, currentOrderId]
            );
            await db.run(
              "UPDATE workshop SET Vagas = Vagas - ? WHERE ID_Workshop = ?",
              [item.Quantidade, item.ID_Workshop]
            );
          }
        }
      }
    } else {
      // Create new draft
      const result = await db.run(
        "INSERT INTO encomenda (ID_Cliente, Data_Encomenda, Total, Status, Morada, Telefone, Nome, Apelido, Custo_Envio, Tipo_Envio) VALUES (?, CURRENT_TIMESTAMP, ?, 'Pendente', ?, ?, ?, ?, ?, ?)",
        [
          req.user.id,
          total,
          address,
          phone,
          nome,
          apelido,
          shippingCost,
          shippingType,
        ],
      );
      currentOrderId = result.lastID;

      // Save items
      for (const item of items) {
        if (item.ID_Produto) {
          await db.run(
            "INSERT INTO item_encomenda (ID_Encomenda, ID_Produto, Quantidade, Preco_Unitario) VALUES (?, ?, ?, ?)",
            [currentOrderId, item.ID_Produto, item.Quantidade, item.Preco],
          );
          await db.run(
            "UPDATE produto SET Stock = Stock - ? WHERE ID_Produto = ?",
            [item.Quantidade, item.ID_Produto],
          );
        } else if (item.ID_Workshop) {
          await db.run(
            "INSERT INTO reserva_workshop (ID_Workshop, ID_Cliente, ID_Encomenda, Status) VALUES (?, ?, ?, 'Pendente')",
            [item.ID_Workshop, req.user.id, currentOrderId]
          );
          await db.run(
            "UPDATE workshop SET Vagas = Vagas - ? WHERE ID_Workshop = ?",
            [item.Quantidade, item.ID_Workshop]
          );
        }
      }

      // Clear cart
      if (!orderId) {
        await db.run(
          "DELETE FROM item_carrinho WHERE ID_Carrinho = (SELECT ID_Carrinho FROM carrinho WHERE ID_Cliente = ?)",
          [req.user.id],
        );
      }
    }

    res.json({ orderId: currentOrderId });
  } catch (error) {
    console.error("Checkout init error:", error);
    res.status(500).json({ error: "Falha ao inicializar encomenda" });
  }
});

