app.delete("/api/user/orders/:id", authenticateToken, async (req, res) => {
  try {
    const { id } = req.params;
    const order = await db.get(
      "SELECT Status, ID_Cliente, Data_Encomenda FROM encomenda WHERE ID_Encomenda = ?",
      [id]
    );

    if (!order) return res.status(404).json({ error: "Order not found" });
    if (order.ID_Cliente !== req.user.id) return res.status(403).json({ error: "Access denied" });
    // Fetch items with beekeeper info
    const items = await db.all(
      `SELECT ie.ID_Produto, ie.Quantidade, p.Nome, p.ID_Apicultor, c.Email as ApicultorEmail 
       FROM item_encomenda ie 
       JOIN produto p ON ie.ID_Produto = p.ID_Produto 
       LEFT JOIN cliente c ON p.ID_Apicultor = c.ID_Cliente 
       WHERE ie.ID_Encomenda = ?`,
      [id]
    );

    // Group by beekeeper email
    const beekeeperItems = {};
    for (const item of items) {
      if (item.ApicultorEmail) {
        if (!beekeeperItems[item.ApicultorEmail]) beekeeperItems[item.ApicultorEmail] = [];
        beekeeperItems[item.ApicultorEmail].push(item);
      }
      // Restore stock
      await db.run("UPDATE produto SET Stock = Stock + ? WHERE ID_Produto = ?", [item.Quantidade, item.ID_Produto]);
    }

    // Fetch workshops with apicultor info to restore vagas and notify if paid
    const workshopsRes = await db.all(
      `SELECT rw.*, w.Titulo, w.ID_Apicultor, c.Email as ApicultorEmail 
       FROM reserva_workshop rw
       JOIN workshop w ON rw.ID_Workshop = w.ID_Workshop
       LEFT JOIN cliente c ON w.ID_Apicultor = c.ID_Cliente
       WHERE rw.ID_Encomenda = ?`,
      [id]
    );

    // Group by apicultor for workshops notifications
    const beekeeperWorkshops = {};
    for (const rw of workshopsRes) {
      if (rw.ApicultorEmail) {
        if (!beekeeperWorkshops[rw.ApicultorEmail]) beekeeperWorkshops[rw.ApicultorEmail] = [];
        beekeeperWorkshops[rw.ApicultorEmail].push(rw);
      }
      // Restore vagas (quantity is 1 per reservation row)
      await db.run("UPDATE workshop SET Vagas = Vagas + 1 WHERE ID_Workshop = ?", [rw.ID_Workshop]);
    }

    // Delete items, workshops and order
    await db.run("DELETE FROM item_encomenda WHERE ID_Encomenda = ?", [id]);
    await db.run("DELETE FROM reserva_workshop WHERE ID_Encomenda = ?", [id]);
    await db.run("DELETE FROM encomenda WHERE ID_Encomenda = ?", [id]);

    // Send emails to beekeepers for products
    if (mailTransporter) {
      for (const email of Object.keys(beekeeperItems)) {
        let itemsHtml = "<ul>";
        for (const item of beekeeperItems[email]) {
          itemsHtml += `<li>${item.Quantidade}x ${item.Nome}</li>`;
        }
        itemsHtml += "</ul>";

        const mailOptions = {
          from: `"Hexomel" <${process.env.EMAIL_USER}>`,
          to: email,
          subject: `⚠️ A Encomenda #${id} foi cancelada pelo cliente`,
          html: `
            <div style="font-family: Arial, sans-serif; color: #333;">
              <h2 style="color: #dc2626;">Encomenda Cancelada</h2>
              <p>O cliente cancelou a encomenda <strong>#${id}</strong> que continha os seguintes produtos seus:</p>
              ${itemsHtml}
              <p>O stock destes produtos foi automaticamente reposto na loja.</p>
              <br/>
              <p>Com os melhores cumprimentos,<br/>A equipa Hexomel</p>
            </div>
          `
        };
        mailTransporter.sendMail(mailOptions).catch(err => console.error("Error sending cancellation email to beekeeper:", err));
      }

      // Send emails to beekeepers for workshops
      for (const email of Object.keys(beekeeperWorkshops)) {
        let itemsHtml = "<ul>";
        for (const rw of beekeeperWorkshops[email]) {
          itemsHtml += `<li>1x Vaga no workshop "${rw.Titulo}"</li>`;
        }
        itemsHtml += "</ul>";

        const mailOptions = {
          from: `"Hexomel" <${process.env.EMAIL_USER}>`,
          to: email,
          subject: `⚠️ A reserva de Workshop #${id} foi cancelada`,
          html: `
            <div style="font-family: Arial, sans-serif; color: #333;">
              <h2 style="color: #dc2626;">Reserva Cancelada</h2>
              <p>O cliente cancelou a reserva/compra da encomenda <strong>#${id}</strong> que continha as vagas nos seus workshops:</p>
              ${itemsHtml}
              <p>As vagas correspondentes foram repostas.</p>
              <br/>
              <p>Com os melhores cumprimentos,<br/>A equipa Hexomel</p>
            </div>
          `
        };
        mailTransporter.sendMail(mailOptions).catch(err => console.error("Error sending workshop cancellation email:", err));
      }
    }

    res.json({ message: "Encomenda eliminada com sucesso" });
  } catch (error) {
    console.error("Delete user order error:", error);
    res.status(500).json({ error: "Database error" });
  }
});

