async function sendReceiptEmail(orderId) {
  if (!mailTransporter) {
    console.log(`📧 Email skipped (no SMTP) for order #${orderId}`);
    return;
  }
  try {
    const order = await db.get(
      "SELECT * FROM encomenda WHERE ID_Encomenda = ?",
      [orderId],
    );
    if (!order) return;

    const customer = await db.get(
      "SELECT Nome, Email FROM cliente WHERE ID_Cliente = ?",
      [order.ID_Cliente],
    );
    if (!customer || !customer.Email) return;

    const prodItems = await db.all(
      `SELECT ie.*, p.Nome, p.Imagem, a.Nome as ApicultorNome
       FROM item_encomenda ie 
       JOIN produto p ON ie.ID_Produto = p.ID_Produto 
       LEFT JOIN cliente a ON p.ID_Apicultor = a.ID_Cliente
       WHERE ie.ID_Encomenda = ?`,
      [orderId],
    );

    const wsItems = await db.all(
      `SELECT rw.*, w.Titulo as Nome, w.Imagem, 1 as Quantidade, w.Preco as Preco_Unitario, a.Nome as ApicultorNome
       FROM reserva_workshop rw
       JOIN workshop w ON rw.ID_Workshop = w.ID_Workshop
       LEFT JOIN cliente a ON w.ID_Apicultor = a.ID_Cliente
       WHERE rw.ID_Encomenda = ?`,
      [orderId]
    );

    const items = [
      ...prodItems,
      ...wsItems
    ];

    const html = generateReceiptHTML(
      order,
      items,
      customer.Nome,
      customer.Email,
    );

    const mailAttachments = [
      {
        filename: "logo_hexomel.webp",
        path: "../frontend/public/images/logo_hexomel.webp",
        cid: "logo",
      }
    ];

    items.forEach((i, index) => {
      let imagePath = "../frontend/public/images/default-product.png";
      if (i.Imagem) {
        // Ensure we are pointing inside the images directory if it's just a filename
        let cleanPath = i.Imagem.startsWith('/') ? i.Imagem.substring(1) : i.Imagem;
        if (!cleanPath.startsWith('images/') && !cleanPath.startsWith('uploads/')) {
            cleanPath = `images/${cleanPath}`;
        }
        imagePath = path.join(__dirname, "../frontend/public", cleanPath);
        // Fallback check can be added if needed, but assuming valid path
      }
      mailAttachments.push({
        filename: `prod_${index}.png`,
        path: imagePath,
        cid: `prod_${index}`
      });
    });

    await mailTransporter.sendMail({
      from: process.env.SMTP_FROM || "Hexomel <hexomelpap@gmail.com>",
      to: customer.Email,
      subject: `🍯 Recibo da Encomenda #${orderId} — Hexomel`,
      html,
      attachments: mailAttachments,
    });
    console.log(
      `📧 Receipt email sent for order #${orderId} to ${customer.Email}`,
    );
  } catch (err) {
    console.error(
      `📧 Failed to send receipt email for order #${orderId}:`,
      err.message,
    );
  }
}

